23: // Callback for freeing managed resources
24: type ICloseHandler interface {
25: 	Close()
26: }
27: 
28: // Close handler equivalent to a no-op. Used by default
29: // when no resources have to be cleaned.
30: type EmptyHandler struct{}
31: 
32: func (EmptyHandler) Close() {}
33: 
34: // Close handler to close an SSH client
35: type CloseSSHCLient struct {
36: 	// Reference to the used SSH client
37: 	sshClient *ssh.Client
38: }
39: 
40: func (scp CloseSSHCLient) Close() {
41: 	scp.sshClient.Close()
42: }
43: 
44: type PassThru func(r io.Reader, total int64) io.Reader
45: 
46: type Client struct {
47: 	// Host the host to connect to.
48: 	Host string
49: 
50: 	// ClientConfig the client config to use.
51: 	ClientConfig *ssh.ClientConfig
52: 
53: 	// Keep the ssh client around for generating new sessions
54: 	sshClient *ssh.Client
55: 
56: 	// Timeout the maximal amount of time to wait for a file transfer to complete.
57: 	// Deprecated: use context.Context for each function instead.
58: 	Timeout time.Duration
59: 
60: 	// RemoteBinary the absolute path to the remote SCP binary.
61: 	RemoteBinary string
62: 
63: 	// Handler called when calling `Close` to clean up any remaining
64: 	// resources managed by `Client`.
65: 	closeHandler ICloseHandler
66: }
67: 
68: // Connect connects to the remote SSH server, returns an error if it couldn't establish a session to the SSH server.
69: // This method is NOT meant to be called when the client was created through `NewClientBySSH` as an SSH 
70: // connection will already exist.
71: func (a *Client) Connect() error {
72: 	client, err := ssh.Dial("tcp", a.Host, a.ClientConfig)
73: 	if err != nil {
74: 		return err
75: 	}
76: 
77: 	a.sshClient = client
78: 	a.closeHandler = CloseSSHCLient{sshClient: client}
79: 	return nil
80: }
81: 
82: // Returns the underlying SSH client, this should be used carefully as
83: // it will be closed by `client.Close`.
84: func (a *Client) SSHClient() *ssh.Client {
85: 	return a.sshClient
86: }
