88: // CopyFromFile copies the contents of an os.File to a remote location, it will get the length of the file by looking it up from the filesystem.
89: func (a *Client) CopyFromFile(
90: 	ctx context.Context,
91: 	file os.File,
92: 	remotePath string,
93: 	permissions string,
94: ) error {
95: 	return a.CopyFromFilePassThru(ctx, file, remotePath, permissions, nil)
96: }
97: 
98: // CopyFromFilePassThru copies the contents of an os.File to a remote location, it will get the length of the file by looking it up from the filesystem.
99: // Access copied bytes by providing a PassThru reader factory.
100: func (a *Client) CopyFromFilePassThru(
101: 	ctx context.Context,
102: 	file os.File,
103: 	remotePath string,
104: 	permissions string,
105: 	passThru PassThru,
106: ) error {
107: 	stat, err := file.Stat()
108: 	if err != nil {
109: 		return fmt.Errorf("failed to stat file: %w", err)
110: 	}
111: 	return a.CopyPassThru(ctx, &file, remotePath, permissions, stat.Size(), passThru)
112: }
113: 
114: // CopyFile copies the contents of an io.Reader to a remote location, the length is determined by reading the io.Reader until EOF
115: // if the file length in know in advance please use "Copy" instead.
116: func (a *Client) CopyFile(
117: 	ctx context.Context,
118: 	fileReader io.Reader,
119: 	remotePath string,
120: 	permissions string,
121: ) error {
122: 	return a.CopyFilePassThru(ctx, fileReader, remotePath, permissions, nil)
123: }
124: 
125: // CopyFilePassThru copies the contents of an io.Reader to a remote location, the length is determined by reading the io.Reader until EOF
126: // if the file length in know in advance please use "Copy" instead.
127: // Access copied bytes by providing a PassThru reader factory.
128: func (a *Client) CopyFilePassThru(
129: 	ctx context.Context,
130: 	fileReader io.Reader,
131: 	remotePath string,
132: 	permissions string,
133: 	passThru PassThru,
134: ) error {
135: 	contentsBytes, err := ioutil.ReadAll(fileReader)
136: 	if err != nil {
137: 		return fmt.Errorf("failed to read all data from reader: %w", err)
138: 	}
139: 	bytesReader := bytes.NewReader(contentsBytes)
140: 
141: 	return a.CopyPassThru(
142: 		ctx,
143: 		bytesReader,
144: 		remotePath,
145: 		permissions,
146: 		int64(len(contentsBytes)),
147: 		passThru,
148: 	)
149: }
