169: // checkResponse checks the response it reads from the remote, and will return a single error in case
170: // of failure.
171: func checkResponse(r io.Reader) error {
172: 	_, err := ParseResponse(r, nil)
173: 	if err != nil {
174: 		return err
175: 	}
176: 
177: 	return nil
178: 
179: }
