181: // Copy copies the contents of an io.Reader to a remote location.
182: func (a *Client) Copy(
183: 	ctx context.Context,
184: 	r io.Reader,
185: 	remotePath string,
186: 	permissions string,
187: 	size int64,
188: ) error {
189: 	return a.CopyPassThru(ctx, r, remotePath, permissions, size, nil)
190: }
191: 
192: // CopyPassThru copies the contents of an io.Reader to a remote location.
193: // Access copied bytes by providing a PassThru reader factory
194: func (a *Client) CopyPassThru(
195: 	ctx context.Context,
196: 	r io.Reader,
197: 	remotePath string,
198: 	permissions string,
199: 	size int64,
200: 	passThru PassThru,
201: ) error {
202: 	session, err := a.sshClient.NewSession()
203: 	if err != nil {
204: 		return fmt.Errorf("Error creating ssh session in copy to remote: %v", err)
205: 	}
206: 	defer session.Close()
207: 
208: 	stdout, err := session.StdoutPipe()
209: 	if err != nil {
210: 		return err
211: 	}
212: 	w, err := session.StdinPipe()
213: 	if err != nil {
214: 		return err
215: 	}
216: 	defer w.Close()
217: 
218: 	if passThru != nil {
219: 		r = passThru(r, size)
220: 	}
221: 
222: 	filename := path.Base(remotePath)
223: 
224: 	// Start the command first and get confirmation that it has been started
225: 	// before sending anything through the pipes.
226: 	err = session.Start(fmt.Sprintf("%s -qt %q", a.RemoteBinary, remotePath))
227: 	if err != nil {
228: 		return err
229: 	}
230: 
231: 	wg := sync.WaitGroup{}
232: 	wg.Add(2)
233: 
234: 	errCh := make(chan error, 2)
235: 
236: 	// SCP protocol and file sending
237: 	go func() {
238: 		defer wg.Done()
239: 		defer w.Close()
240: 
241: 		_, err = fmt.Fprintln(w, "C"+permissions, size, filename)
242: 		if err != nil {
243: 			errCh <- err
244: 			return
245: 		}
246: 
247: 		if err = checkResponse(stdout); err != nil {
248: 			errCh <- err
249: 			return
250: 		}
251: 
252: 		_, err = io.Copy(w, r)
253: 		if err != nil {
254: 			errCh <- err
255: 			return
256: 		}
257: 
258: 		_, err = fmt.Fprint(w, "\x00")
259: 		if err != nil {
260: 			errCh <- err
261: 			return
262: 		}
263: 
264: 		if err = checkResponse(stdout); err != nil {
265: 			errCh <- err
266: 			return
267: 		}
268: 	}()
269: 
270: 	// Wait for the process to exit
271: 	go func() {
272: 		defer wg.Done()
273: 		err := session.Wait()
274: 		if err != nil {
275: 			errCh <- err
276: 			return
277: 		}
278: 	}()
279: 
280: 	// If there is a timeout, stop the transfer if it has been exceeded
281: 	if a.Timeout > 0 {
282: 		var cancel context.CancelFunc
283: 		ctx, cancel = context.WithTimeout(ctx, a.Timeout)
284: 		defer cancel()
285: 	}
286: 
287: 	// Wait for one of the conditions (error/timeout/completion) to occur
288: 	if err := wait(&wg, ctx); err != nil {
289: 		return err
290: 	}
291: 
292: 	close(errCh)
293: 
294: 	// Collect any errors from the error channel
295: 	for err := range errCh {
296: 		if err != nil {
297: 			return err
298: 		}
299: 	}
300: 
301: 	return nil
302: }
