304: // CopyFromRemote copies a file from the remote to the local file given by the `file`
305: // parameter. Use `CopyFromRemotePassThru` if a more generic writer
306: // is desired instead of writing directly to a file on the file system.
307: func (a *Client) CopyFromRemote(ctx context.Context, file *os.File, remotePath string) error {
308: 	return a.CopyFromRemotePassThru(ctx, file, remotePath, nil)
309: }
