311: // CopyFromRemotePassThru copies a file from the remote to the given writer. The passThru parameter can be used
312: // to keep track of progress and how many bytes that were download from the remote.
313: // `passThru` can be set to nil to disable this behaviour.
314: func (a *Client) CopyFromRemotePassThru(
315: 	ctx context.Context,
316: 	w io.Writer,
317: 	remotePath string,
318: 	passThru PassThru,
319: ) error {
320: 	_, err := a.copyFromRemote(ctx, w, remotePath, passThru, false)
321: 
322: 	return err
323: }
